/**
 * Normalize a talent name for O(1) lookup in TALENT_LIBRARY.
 * @param {string} name
 * @returns {string}
 */
export function normalizeTalentLibraryName(name) {
  let s = String(name || "")
    .replace(/\*\*.*$/g, "")
    .replace(/\s*\([^)]*\)\s*$/g, "")
    .toLowerCase()
    .replace(/['’"]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

  // Strip trailing "talent" or "talents" if preceded by other words (e.g. "mage entry talent" -> "mage entry")
  if (/\s+(?:track\s*)?talents?$/i.test(s)) {
    s = s.replace(/\s+(?:track\s*)?talents?$/i, "").trim();
  }
  return s;
}

// Build primary name map and disambiguated class::name / stack::name map at module load
export const TALENT_LIBRARY = {};
export const TALENT_LIBRARY_BY_KEY = {};

for (const entry of Object.values(TALENT_LIBRARY_BY_ID)) {
  const normName = entry.normalizedName;
  const strippedName = normName.replace(/\s+(?:track\s*)?talents?$/i, "").trim();
  const withTalentSuffix = `${strippedName} talent`;
  const normClass = normalizeTalentLibraryName(entry.class);
  const normStack = normalizeTalentLibraryName(entry.stack);
  const shortStack = normStack.replace(/\s+(?:track|stack|talents)$/i, "").trim();

  const registerKey = (nameVariant) => {
    TALENT_LIBRARY_BY_KEY[`${normClass}::${nameVariant}`] = entry;
    TALENT_LIBRARY_BY_KEY[`${normStack}::${nameVariant}`] = entry;
    if (shortStack) {
      TALENT_LIBRARY_BY_KEY[`${shortStack}::${nameVariant}`] = entry;
    }

    if (!TALENT_LIBRARY[nameVariant]) {
      TALENT_LIBRARY[nameVariant] = { ...entry, overloads: [entry] };
    } else if (!TALENT_LIBRARY[nameVariant].overloads.some(o => o.id === entry.id)) {
      TALENT_LIBRARY[nameVariant].overloads.push(entry);
      if (entry.category === "specialization" || entry.category === "magic") {
        TALENT_LIBRARY[nameVariant] = { ...entry, overloads: TALENT_LIBRARY[nameVariant].overloads };
      }
    }
  };

  registerKey(normName);
  if (strippedName && strippedName !== normName) registerKey(strippedName);
  registerKey(withTalentSuffix);
}

/**
 * Look up a canonical talent entry from TALENT_LIBRARY by Item document, raw object, or talent name.
 * Disambiguates homonymous talents (e.g. "Hardy" in Berzerker vs Defense Stack, or "Poisoner" in Rogue vs Skill Stack)
 * using `contextClassOrTrack`, item flags, item tags, prerequisites, or folder names.
 *
 * @param {Item|object|string} itemOrName
 * @param {string|null} [contextClassOrTrack=null]
 * @returns {object|null}
 */
export function getTalentLibraryEntry(itemOrName, contextClassOrTrack = null) {
  if (!itemOrName) return null;

  // 1. Direct canonical ID check
  if (typeof itemOrName === "string" && /^T-\d{4}$/i.test(itemOrName.trim())) {
    return TALENT_LIBRARY_BY_ID[itemOrName.trim().toUpperCase()] || null;
  }
  if (typeof itemOrName === "object") {
    const flagId = itemOrName.flags?.["mythcraft-essence-sheet"]?.canonicalTalentId || itemOrName.canonicalTalentId;
    if (flagId && TALENT_LIBRARY_BY_ID[flagId]) {
      return TALENT_LIBRARY_BY_ID[flagId];
    }
  }

  const rawName = typeof itemOrName === "string"
    ? itemOrName
    : (itemOrName.name || itemOrName.itemName || "");
  if (!rawName) return null;

  const normName = normalizeTalentLibraryName(rawName);
  if (!normName) return null;
  const strippedName = normName.replace(/\s+(?:track\s*)?talents?$/i, "").trim();
  const withTalent = `${strippedName} talent`;

  // 2. Context-disambiguated lookup (class::name or stack::name)
  if (contextClassOrTrack) {
    const normCtx = normalizeTalentLibraryName(contextClassOrTrack);
    const shortCtx = normCtx.replace(/\s+(?:track|stack|talents)$/i, "").trim();
    const tryKeys = [
      `${normCtx}::${normName}`, `${normCtx}::${strippedName}`, `${normCtx}::${withTalent}`,
      `${shortCtx}::${normName}`, `${shortCtx}::${strippedName}`, `${shortCtx}::${withTalent}`
    ];
    for (const k of tryKeys) {
      if (TALENT_LIBRARY_BY_KEY[k]) return TALENT_LIBRARY_BY_KEY[k];
    }
  }

  const primary = TALENT_LIBRARY[normName] || TALENT_LIBRARY[strippedName] || TALENT_LIBRARY[withTalent];
  if (!primary) return null;

  // 3. If there are multiple overloads for this name and we have an Item/object, disambiguate via tags/prereqs/folder
  if (primary.overloads?.length > 1 && typeof itemOrName === "object") {
    const sys = itemOrName.system || {};
    const rawTags = Array.isArray(sys.tags)
      ? sys.tags
      : (sys.tags instanceof Set ? Array.from(sys.tags) : []);
    const itemTags = rawTags.map(t => String(typeof t === "string" ? t : (t?.name || t?.id || "")).toLowerCase());
    const itemPrereq = normalizeTalentLibraryName(sys.prerequisites || sys.prerequisite || itemOrName.prereq || "");
    const folderName = normalizeTalentLibraryName(itemOrName.folder?.name || itemOrName.trackName || itemOrName.className || "");

    for (const candidate of primary.overloads) {
      const candClass = normalizeTalentLibraryName(candidate.class);
      const candStack = normalizeTalentLibraryName(candidate.stack).replace(/\s+(?:track|stack|talents)$/i, "").trim();
      if (folderName && (folderName.includes(candClass) || (candStack && folderName.includes(candStack)))) {
        return candidate;
      }
      if (itemTags.some(t => candidate.tags.map(ct => ct.toLowerCase()).includes(t))) {
        return candidate;
      }
      if (itemPrereq && candidate.prereq && normalizeTalentLibraryName(candidate.prereq) === itemPrereq) {
        return candidate;
      }
    }
  }

  return primary;
}

/**
 * Returns cloned, ready-to-embed Foundry VTT ActiveEffect data objects for a talent.
 * Returns an empty array if the talent is narrative/manual-only (`automatable: false`).
 *
 * @param {Item|object|string} itemOrName
 * @param {Actor|null} [actor=null]
 * @param {string|null} [contextClassOrTrack=null]
 * @returns {Array<object>}
 */
export function getTalentActiveEffectsData(itemOrName, actor = null, contextClassOrTrack = null) {
  const entry = getTalentLibraryEntry(itemOrName, contextClassOrTrack);
  if (!entry || !entry.automatable || !Array.isArray(entry.activeEffects) || entry.activeEffects.length === 0) {
    return [];
  }

  const itemImg = (typeof itemOrName === "object" && itemOrName?.img) ? itemOrName.img : null;

  return entry.activeEffects.map(ae => {
    const cloned = structuredClone ? structuredClone(ae) : JSON.parse(JSON.stringify(ae));
    if (itemImg && (!cloned.img || cloned.img === "icons/svg/book.svg")) {
      cloned.img = itemImg;
    }
    return cloned;
  });
}

/**
 * Returns the structured prerequisite rules for a talent from TALENT_LIBRARY.
 * @param {Item|object|string} itemOrName
 * @param {string|null} [contextClassOrTrack=null]
 * @returns {object|null}
 */
export function getTalentPrerequisiteRules(itemOrName, contextClassOrTrack = null) {
  const entry = getTalentLibraryEntry(itemOrName, contextClassOrTrack);
  return entry?.prerequisiteRules || null;
}

/**
 * Returns the structured granted talents and bonus track picks for a talent from TALENT_LIBRARY.
 * @param {Item|object|string} itemOrName
 * @param {string|null} [contextClassOrTrack=null]
 * @returns {Array<object>}
 */
export function getTalentGrantsAndPicks(itemOrName, contextClassOrTrack = null) {
  const entry = getTalentLibraryEntry(itemOrName, contextClassOrTrack);
  return Array.isArray(entry?.grantedTalents) ? entry.grantedTalents : [];
}
